<div class="container py-4"><div class="mb-4"><h1 class="h3 mb-1">Livestream</h1><p class="text-muted mb-0">Theo dõi các trận đấu đang phát và sắp phát trong câu lạc bộ.</p></div><div class="row g-4"><?php if (!$channels): ?><div class="col-12"><div class="alert alert-light">Hiện chưa có livestream công khai.</div></div><?php endif; ?><?php foreach ($channels as $channel): ?><div class="col-md-6"><article class="card shadow-sm h-100"><div class="ratio ratio-16x9 bg-dark"><?php if (!empty($channel->embed_url)): ?><iframe src="<?= esc($channel->embed_url) ?>" title="<?= esc($channel->name) ?>" allow="autoplay; encrypted-media; picture-in-picture" allowfullscreen loading="lazy" referrerpolicy="strict-origin-when-cross-origin"></iframe><?php else: ?><div class="d-flex align-items-center justify-content-center text-white">Chưa có embed</div><?php endif; ?></div><div class="card-body"><h2 class="h5"><?= esc($channel->name) ?></h2><div class="small text-muted"><?= esc($channel->provider) ?> · <?= esc($channel->status) ?> · <?= esc($channel->scheduled_at ?? '') ?></div><a class="btn btn-sm btn-outline-primary mt-3" href="<?= esc($channel->stream_url) ?>" target="_blank" rel="noopener noreferrer">Mở kênh</a></div></article></div><?php endforeach; ?></div></div>
